const standingMatchesOfVoucher = `-- name: StandingMatchesOfVoucher :many
SELECT id, statement_line_id, kind, request_key, reason, voucher_id, supplier_payment_id, bank_rule_id, bank_rule_version, matched_at, matched_by_user_id, undone_at, undone_by_user_id, undo_voucher_id FROM accounting.statement_matches WHERE voucher_id = $1::bigint AND undone_at IS NULL ORDER BY id
`

func (q *Queries) StandingMatchesOfVoucher(ctx context.Context, voucherID int64) ([]AccountingStatementMatch, error) {
	rows, err := q.db.Query(ctx, standingMatchesOfVoucher, voucherID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AccountingStatementMatch
	for rows.Next() {
		var i AccountingStatementMatch
		if err := rows.Scan(
			&i.ID,
			&i.StatementLineID,
			&i.Kind,
			&i.RequestKey,
			&i.Reason,
			&i.VoucherID,
			&i.SupplierPaymentID,
			&i.BankRuleID,
			&i.BankRuleVersion,
			&i.MatchedAt,
			&i.MatchedByUserID,
			&i.UndoneAt,
			&i.UndoneByUserID,
			&i.UndoVoucherID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const statementBalanceAt = `-- name: StatementBalanceAt :one
WITH base AS (
    SELECT s.period_to, s.closing_balance FROM accounting.statements s
    WHERE s.bank_account_id = $1 AND s.closing_balance IS NOT NULL
      AND s.period_to <= $2::date
    ORDER BY s.period_to DESC, s.id DESC LIMIT 1
)
SELECT EXISTS (SELECT 1 FROM base)::boolean AS has_balance,
    (coalesce((SELECT closing_balance FROM base), 0) + coalesce((SELECT sum(l.amount) FROM accounting.statement_lines l
        WHERE l.bank_account_id = $1 AND l.booked_on <= $2::date
          AND l.booked_on > coalesce((SELECT period_to FROM base), '-infinity'::date)), 0))::text AS balance
`

type StatementBalanceAtParams struct {
	BankAccountID int64
	Through       time.Time
}

type StatementBalanceAtRow struct {
	HasBalance bool
	Balance    string
}

// StatementBalanceAt is the account's balance by its statements at the end of
// a day: the latest closing balance given on or before it, and every line
// booked after that statement's period through the day. has_balance is false
// when no statement gave one.
func (q *Queries) StatementBalanceAt(ctx context.Context, arg StatementBalanceAtParams) (StatementBalanceAtRow, error) {
	row := q.db.QueryRow(ctx, statementBalanceAt, arg.BankAccountID, arg.Through)
	var i StatementBalanceAtRow
	err := row.Scan(&i.HasBalance, &i.Balance)
	return i, err
}

